import json,collections,re,glob,statistics
valsets=[]; all_val=set()
for path in sorted(glob.glob('results/baseline63/validation/*.jsonl'),key=lambda p:int(p.rsplit('/',1)[-1].split('.')[0])):
    rows=[json.loads(l) for l in open(path)]
    ids={(r['steps'][0]['split'],r['steps'][0]['task_id']) for r in rows};valsets.append(ids);all_val|={x[1] for x in ids}
    print(path, 'unique_ids',len(ids),'split_success',dict(collections.Counter({sp:sum(r['score'] for r in rows if r['steps'][0]['split']==sp) for sp in ['valid_seen','valid_unseen']})), 'mean_turns',statistics.mean(r['steps'][0]['num_steps'] for r in rows),'max_action_calls',max(r['output'].count('<tool_call>') for r in rows),'reward_success_disagreement',sum(r['score']!=float(r['steps'][0]['success']) for r in rows))
