train_ids=set()
for path in glob.glob('results/baseline63/rollouts/*.jsonl'):
    rows=[json.loads(l) for l in open(path)];train_ids|={r['steps'][0]['task_id'] for r in rows}
print('saved_train_tasks',len(train_ids),'overlap_with_eval',len(train_ids&all_val))
s=open('results/baseline63/train.log').read();metrics=[]
for l in s.splitlines():
    m=re.search(r'step:(\d+) - ',l)
    if not m:continue
    d={'step':int(m[1])}
    for k,v in re.findall(r'([^\s]+):([-+\d.eE]+)(?= - |$)',l[m.end():]):
        try:d[k]=float(v)
